// 原件缺字段、重复键和未知版本均拒绝；冷恢复不发薪、不补写接受或到岗事实。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "estate_employment_codec.hpp"
#include "../../local_economy/economic_payload_guard.hpp"
namespace hanmo::resident {
Outcome<EstateEmploymentCatalog> decode_estate_employment_catalog(const BoundaryValue& input){auto unique=validate_economic_payload_fields(input);if(!unique.ok)return {false,{},unique.error};try{auto out=dynamic_economy_codec::decode_root<EstateEmploymentCatalog>(input,estate_employment_module);if(out.version!=1)boundary::fail("UnsupportedEstateEmploymentVersion",estate_employment_module);return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& error){return {false,{},error.error};}}
Outcome<EstateEmploymentState> decode_estate_employment_state(const BoundaryValue& input){auto unique=validate_economic_payload_fields(input);if(!unique.ok)return {false,{},unique.error};try{auto out=dynamic_economy_codec::decode_root<EstateEmploymentState>(input,estate_employment_module);if(out.version!=1)boundary::fail("UnsupportedEstateEmploymentVersion",estate_employment_module);return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& error){return {false,{},error.error};}}
Status emit_estate_employment_state_fields(ProjectionWriter& writer,const EstateEmploymentState& state){try{if(state.version!=1)boundary::fail("UnsupportedEstateEmploymentVersion",estate_employment_module);return dynamic_economy_codec::emit_fields(writer,state);}catch(const boundary::DecodeFailure&failure){return writer.reject(failure.error.original.code,failure.error.original.path);}}
BoundaryValue encode_estate_employment_state(const EstateEmploymentState& state){BoundaryValue out;BoundaryProjectionWriter writer(out);auto valid=writer.object("",[&](auto&fields){return emit_estate_employment_state_fields(fields,state);});if(valid.ok)valid=writer.finish();if(!valid.ok)throw boundary::DecodeFailure{valid.error};return out;}
Status visit_estate_employment_checkpoint(CodecVisitor& visitor,EstateEmploymentState& state){if(!visitor.reading()&&state.version!=1)return visitor.reject("UnsupportedEstateEmploymentVersion",estate_employment_module);auto result=dynamic_economy_codec::checkpoint(visitor,estate_employment_module,state);if(!result.ok)return result;return state.version==1?visitor.status():visitor.reject("UnsupportedEstateEmploymentVersion",estate_employment_module);}
Outcome<EstateEmploymentState> make_initial_estate_employment(const CommonStore& c,const EstateState& estates,const LocalEconomyState& economy){if(economy.last_step_tick!=c.tick())return {false,{},common_failure("EstateEmploymentInitialTickMismatch").error};for(const auto& row:estates.estates.rows())if(row.second.last_tick!=c.tick())return {false,{},common_failure("EstateEmploymentInitialTickMismatch",row.first).error};EstateEmploymentState state;state.initialized_tick=state.last_step_tick=c.tick();return {true,std::move(state),{}};}
}
